// frontend/src/config/firebase.js
import { initializeApp } from "firebase/app";
import {
  getAuth,
  onAuthStateChanged as fbOnAuthStateChanged,
  signInWithCustomToken as fbSignInWithCustomToken,
} from "firebase/auth";
import { getFirestore } from "firebase/firestore";

const firebaseConfig = {
  apiKey: "AIzaSyDl5_9mrcur28MY1fYTMHJ-X4C_sNekoFg",
  authDomain: "careerguidanceplatform-14ca1.firebaseapp.com",
  projectId: "careerguidanceplatform-14ca1",
  storageBucket: "careerguidanceplatform-14ca1.firebasestorage.app",
  messagingSenderId: "427570744807",
  appId: "1:427570744807:web:4deeb0638b3778e36fc142",
  measurementId: "G-2HM9CQBK48"
};

const app = initializeApp(firebaseConfig);
export const auth = getAuth(app);
export const db = getFirestore(app);

// Re-export the functions your AuthContext needs
export const onAuthStateChanged = fbOnAuthStateChanged;
export const signInWithCustomToken = fbSignInWithCustomToken;

export default app;
